 void schema(){
  if(schemaReady)return;
  Set<String> cols=new HashSet<>();Cursor c=db.rawQuery("PRAGMA table_info(tx)",null);while(c.moveToNext())cols.add(c.getString(1));c.close();
  for(String col:new String[]{"uuid","person","loan"})if(!cols.contains(col))db.execSQL("ALTER TABLE tx ADD COLUMN "+col+" TEXT NOT NULL DEFAULT ''");
  c=db.rawQuery("SELECT id FROM tx WHERE uuid=''",null);while(c.moveToNext()){ContentValues v=new ContentValues();v.put("uuid",UUID.randomUUID().toString());db.update("tx",v,"id=?",new String[]{c.getString(0)});}c.close();
  db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS tx_uuid ON tx(uuid)");
  db.execSQL("CREATE TABLE IF NOT EXISTS sync_outbox(uuid TEXT PRIMARY KEY, operation TEXT NOT NULL, revision INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS sync_meta(name TEXT PRIMARY KEY, value TEXT NOT NULL)");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS tx_added AFTER INSERT ON tx BEGIN INSERT OR REPLACE INTO sync_outbox VALUES(NEW.uuid,'upsert',coalesce((SELECT revision+1 FROM sync_outbox WHERE uuid=NEW.uuid),1)); END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS tx_edited AFTER UPDATE ON tx BEGIN INSERT OR REPLACE INTO sync_outbox VALUES(NEW.uuid,'upsert',coalesce((SELECT revision+1 FROM sync_outbox WHERE uuid=NEW.uuid),1)); END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS tx_removed AFTER DELETE ON tx BEGIN INSERT OR REPLACE INTO sync_outbox VALUES(OLD.uuid,'delete',coalesce((SELECT revision+1 FROM sync_outbox WHERE uuid=OLD.uuid),1)); END");
  LedgerSyncStore.schema(db);settings=new SettingsStore(db);if(!settings.has("language"))settings.put("language",ml?"ml":"en");else ml=settings.get("language").equals("ml");if(!settings.has("appearance"))settings.put("appearance",dark?"Dark":"Light");else dark=effectiveDark();quickKind=settings.get("defaultKind");try{if(session==null)session=new LedgerSession(db,null);}catch(Exception e){throw new IllegalStateException("Local ledger session could not start",e);}schemaReady=true;
 }
