 void pruneDuePlans(){if(db==null||catalog==null)return;java.util.Set<String> live=new java.util.HashSet<>();try(Cursor c=db.rawQuery("SELECT uuid,amount FROM tx WHERE kind IN ('lent','borrowed')",null)){while(c.moveToNext())if(c.getLong(1)>repaid(c.getString(0)))live.add(DuePlans.key(profileKey(),c.getString(0)));}String scope=profileKey();boolean changed=false;for(String key:new java.util.HashSet<>(DuePlans.prefs(this).getAll().keySet()))if(scope.equals(DuePlans.get(this,key).optString("scope"))&&!live.contains(key)){DuePlans.prefs(this).edit().remove(key).apply();changed=true;}if(changed)DuePlans.schedule(this);}
