 void aboutHisab(){if(accountUi!=null){accountUi.about();return;}dialog().setTitle("Hisab").setMessage(t("by AiCoN\n0.2.2-dev · private development build.\n\nManual entries, budgets and savings plans, with optional Google Drive app-data sync. No bank access, ads, analytics, SMS reading, notification reading or automatic messaging. SMS and WhatsApp handoffs open a reviewed composer; you decide whether to send. Contact links, profile photos and pay-by notes stay on this device. Local-only records never upload automatically. Real-device Google sign-in and Drive behavior still need verification. Encrypted backup is the restore format; CSV and PDF are readable exports.\n\nOriginal code, design and icons. Not financial advice.","by AiCoN\n0.2.2-dev · സ്വകാര്യ വികസന പതിപ്പ്.\n\nനിങ്ങൾ ചേർക്കുന്ന കണക്കുകളും ബജറ്റും സമ്പാദ്യ ലക്ഷ്യങ്ങളും; Google Drive ആപ്പ്-ഡാറ്റ സമന്വയം ഐച്ഛികമാണ്. ബാങ്ക് പ്രവേശനമോ പരസ്യമോ ട്രാക്കിങ്ങോ SMS/നോട്ടിഫിക്കേഷൻ വായനയോ തനിയെ സന്ദേശം അയയ്ക്കലോ ഇല്ല. SMS/WhatsApp സന്ദേശം പരിശോധിക്കാവുന്ന ആപ്പിൽ തുറക്കും; അയയ്ക്കണോ എന്ന് നിങ്ങൾ തീരുമാനിക്കും. കോൺടാക്ട്, പ്രൊഫൈൽ ചിത്രം, തീയതി കുറിപ്പ് എന്നിവ ഈ ഫോണിൽ മാത്രം. ഫോണിലെ കണക്കുകൾ തനിയെ അപ്‌ലോഡ് ചെയ്യില്ല. യഥാർത്ഥ ഉപകരണത്തിലെ Google പ്രവേശനവും Drive പ്രവർത്തനവും ഇനിയും പരിശോധിക്കണം. എൻക്രിപ്റ്റ് ചെയ്ത ബാക്കപ്പാണ് പുനഃസ്ഥാപന രൂപം; CSV, PDF വായിക്കാവുന്ന കയറ്റുമതികളാണ്.\n\nസ്വന്തം കോഡും രൂപവും ഐക്കണുകളും. സാമ്പത്തിക ഉപദേശമല്ല.")).setPositiveButton(t("Done","കഴിഞ്ഞു"),null).setNeutralButton(t("Source code","സോഴ്സ് കോഡ്"),(di,n)->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://github.com/aicon-hub/hisab")))).setNegativeButton("AiCoN",(di,n)->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://aicon-hub.github.io/")))).show();}
 void confirmLocalReset(){if(accountUi!=null&&session.accountLedger()){accountUi.confirmCloudReset();return;}final LedgerSession.FormTicket ticket=session.formTicket();dialog().setTitle(t("Delete all local records?","എല്ലാ കണക്കുകളും നീക്കണോ?")).setMessage(t("Entries, budgets, goals, custom categories/accounts/people and preferences will be cleared. Saved backup and CSV files are not deleted. This cannot be undone.","കണക്കുകളും ബജറ്റുകളും ലക്ഷ്യങ്ങളും സ്വന്തം വിഭാഗങ്ങളും അക്കൗണ്ടുകളും ആളുകളും ക്രമീകരണങ്ങളും നീക്കും. ബാക്കപ്പും CSVയും നീക്കില്ല. തിരിച്ചെടുക്കാനാവില്ല.")).setNegativeButton(t("Cancel","വേണ്ട"),null).setPositiveButton(t("Delete all","എല്ലാം നീക്കുക"),(di,n)->{try{session.editForm(ticket,(db,c,s)->deleteAllRecords());render();}catch(Exception e){toast(e.getMessage());}}).show();}
