 void decorate(TextView view,String type,String name,int size){CatalogStore.Item item=catalog.find(type,name);int fallback=type.equals("person")?16:type.equals("account")?22:name.equals("Transfer")?2:27;CategoryMark mark=new CategoryMark(item==null?fallback:item.icon,entityColor(item==null?"System":item.color));mark.setBounds(0,0,d(size),d(size));view.setCompoundDrawables(mark,null,null,null);view.setCompoundDrawablePadding(d(12));view.setGravity(Gravity.CENTER_VERTICAL);}
