 void chooseOriginalIcon(int chosen,String color,java.util.function.IntConsumer picked){GridView grid=new GridView(this);grid.setNumColumns(3);grid.setPadding(d(12),d(12),d(12),d(12));grid.setHorizontalSpacing(d(4));grid.setVerticalSpacing(d(4));grid.setAdapter(new BaseAdapter(){public int getCount(){return 28;}public Object getItem(int n){return n;}public long getItemId(int n){return n;}public View getView(int n,View old,android.view.ViewGroup parent){TextView tile=text(ml?builtInCategoryLabels[n]:builtInCategories[n],12,n==chosen?ON_PRIMARY:FG,true);tile.setGravity(Gravity.CENTER);tile.setPadding(d(4),d(10),d(4),d(10));tile.setMinHeight(d(106));tile.setBackground(bg(n==chosen?ORANGE:CARD,14));CategoryMark mark=new CategoryMark(n,n==chosen?ON_PRIMARY:entityColor(color));mark.setBounds(0,0,d(44),d(44));tile.setCompoundDrawables(null,mark,null,null);tile.setCompoundDrawablePadding(d(6));return tile;}});AlertDialog choose=dialog().setTitle(t("Original icons","ഐക്കണുകൾ")).setView(grid).setNegativeButton(t("Cancel","വേണ്ട"),null).create();grid.setOnItemClickListener((parent,v,n,id)->{picked.accept(n);choose.dismiss();});choose.show();}
 void removeCatalog(CatalogStore.Item item){if(catalog.references(item)>0){dialog().setTitle(t("Keep your history intact","പഴയ കണക്കുകൾ സൂക്ഷിക്കുക")).setMessage(t("This "+item.type+" is used by entries or budgets. You can edit it, but removing it would break history. No records have been changed.","കണക്കുകളോ ബജറ്റുകളോ ഇത് ഉപയോഗിക്കുന്നു. തിരുത്താം, പക്ഷേ നീക്കിയാൽ പഴയ കണക്കുകൾ ബാധിക്കും. ഒന്നും മാറ്റിയിട്ടില്ല.")).setPositiveButton(t("Done","കഴിഞ്ഞു"),null).show();return;}final LedgerSession.FormTicket ticket=session.formTicket();dialog().setTitle(t("Remove "+item.name+"?",item.name+" നീക്കണോ?")).setMessage(t("No entries or budgets use this item. This removes only the unused item and resets it as a quick-entry default if selected.","കണക്കുകളോ ബജറ്റുകളോ ഇത് ഉപയോഗിക്കുന്നില്ല. ഇത് മാത്രം നീക്കും. ആദ്യ തിരഞ്ഞെടുപ്പാണെങ്കിൽ അതും മാറ്റും.")).setNegativeButton(t("Cancel","വേണ്ട"),null).setPositiveButton(t("Remove","നീക്കുക"),(di,n)->{try{mutateForm(ticket,()->{try{catalog.removeUnused(item.id);}catch(Exception e){throw new IllegalArgumentException(e.getMessage());}});if(activeForm!=null)activeForm.dismiss();render();}catch(Exception e){toast(e.getMessage());}}).show();}
 void editCatalog(String type,CatalogStore.Item existing){LinearLayout f=dialogBody();EditText name=field(t("Name","പേര്"),1);name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});if(existing!=null)name.setText(existing.name);formItem(f,t("Name","പേര്"),name);final int[] icon={existing==null?(type.equals("person")?16:type.equals("account")?22:27):existing.icon};final String[] color={existing==null?"System":existing.color};TextView iconPick=button(t("Choose original icon","ഐക്കൺ തിരഞ്ഞെടുക്കുക"),()->{},false);Runnable previewIcon=()->{CategoryMark mark=new CategoryMark(icon[0],entityColor(color[0]));mark.setBounds(0,0,d(44),d(44));iconPick.setCompoundDrawables(mark,null,null,null);iconPick.setCompoundDrawablePadding(d(12));};previewIcon.run();iconPick.setMinHeight(d(72));iconPick.setText(t("Choose icon","ഐക്കൺ തിരഞ്ഞെടുക്കുക"));iconPick.setOnClickListener(v->chooseOriginalIcon(icon[0],color[0],n->{icon[0]=n;previewIcon.run();}));formItem(f,t("Icon","ഐക്കൺ"),iconPick);TextView colorPick=button(color[0],()->{},false);colorPick.setOnClickListener(v->colourChoices(t("Colour","നിറം"),CatalogStore.COLORS,color[0],choice->{color[0]=choice;colorPick.setText(choice);previewIcon.run();AlertDialog latest=openDialogs.isEmpty()?null:openDialogs.get(openDialogs.size()-1);if(latest!=null)latest.dismiss();}));formItem(f,t("Colour","നിറം"),colorPick);if(existing!=null)f.addView(button(t("Remove unused "+type,"ഉപയോഗിക്കാത്തത് നീക്കുക"),()->removeCatalog(existing),false));f.addView(text(t("Renaming updates existing entries and linked debts without changing amounts. Only unused items can be removed; items in your history stay safe.","പേര് മാറ്റിയാൽ പഴയ കണക്കുകളിലും മാറും. തുക മാറില്ല. ഉപയോഗിക്കാത്തത് മാത്രം നീക്കാം; പഴയ കണക്കുകൾ സൂക്ഷിക്കും."),13,MUTED,false));form(existing==null?t("Add "+type,"പുതിയത് ചേർക്കുക"):t("Edit "+type,"തിരുത്തുക"),f,t("Save","സേവ്"),()->{try{catalog.put(existing==null?null:existing.id,type,name.getText().toString(),icon[0],color[0]);refreshCatalog();}catch(Exception e){throw new IllegalArgumentException(e.getMessage());}});}
 @Override void changeLanguage(){savePreference("language",!ml?"ml":"en");ml=!ml;prefs.edit().putBoolean("ml",ml).apply();render();}
