 @Override String amountUnit(String prefix){return prefix+" · "+(settings==null?"INR":settings.get("currency"));}
 @Override String ru(long value){if(settings==null)return super.ru(value);String currency=settings.get("currency"),grouping=settings.get("grouping"),digits=java.math.BigDecimal.valueOf(value,2).abs().setScale(2).toPlainString();String[] split=digits.split("\\.");String integer=split[0];if(!grouping.equals("None")){StringBuilder out=new StringBuilder();int n=0;for(int i=integer.length()-1;i>=0;i--){if(n>0&&(grouping.equals("Indian")?(n==3||(n>3&&(n-3)%2==0)):n%3==0))out.append(',');out.append(integer.charAt(i));n++;}integer=out.reverse().toString();}String prefix=currency+" ";if(settings.get("amountStyle").equals("Symbol")){switch(currency){case "INR":prefix="₹";break;case "USD":prefix="$";break;case "EUR":prefix="€";break;case "GBP":prefix="£";break;default:prefix=currency+" ";}}return (value<0?"−":"")+prefix+integer+"."+split[1];}
 String displayDate(String iso){try{return java.time.LocalDate.parse(iso).format(java.time.format.DateTimeFormatter.ofPattern(settings.get("dateFormat"),ml?new Locale("ml","IN"):Locale.ENGLISH));}catch(Exception e){return iso;}}
 String defaultEntity(String type,String fallback){String id=settings.get(type.equals("account")?"defaultAccount":"defaultCategory");for(CatalogStore.Item item:catalog.list(type))if(item.id.equals(id))return item.name;return fallback;}
 @Override android.graphics.drawable.Drawable glass(int radius){return settings!=null&&settings.get("surface").equals("Liquid Glass")?liquidGlass(radius):border(CARD);}
 @Override void palette(){if(settings!=null)dark=effectiveDark();super.palette();if(settings!=null&&!settings.get("palette").equals("Dynamic")){ORANGE=entityColor(settings.get("palette"));ON_PRIMARY=dark?0xff06110d:0xffffffff;}boolean liquid=settings!=null&&settings.get("surface").equals("Liquid Glass");boolean pureBlack=!liquid&&dark&&settings!=null&&settings.get("pureBlack").equals("On");if(liquid){BG=android.graphics.Color.BLACK;CARD=0xff08090b;FG=0xfff4f6fa;MUTED=0xffadb4bf;LINE=0xff303740;HERO=0xff0a0c0f;}else if(pureBlack){BG=android.graphics.Color.BLACK;CARD=0xff0b1010;HERO=0xff0d1714;}applyDesignTokens(liquid,pureBlack);}

